            // Les trois derniers de A, et LE bilan de B.
            for(const d of [900,800,700,500])
              if(!reste('rc_photo_'+d+'_bil-photo-face')) return _echec(d+' a été purgé à tort');
            if(reste('rc_photo_600_bil-photo-face')) return _echec('le 4e bilan de A survit');
            if(n!==1) return _echec(n+' suppression(s) au lieu de 1');
            // Ce qu'on ne comprend pas, on n'y touche pas.
            if(!reste('rc_photo_zzz_bil-photo-face')) return _echec('une clé au format inattendu a été supprimée');
            if(!reste('rc_autre_600_x')) return _echec('une clé étrangère a été supprimée');
            // Aucun bilan connu : on ne sait pas ce qui sert encore, donc on
