            CLOUD.pushOne=()=>Promise.resolve();
            currentUser=_ath();
            _fileResilPoser('ab@t',Date.now());
            // _rejouerResiliation est async : on éprouve la logique de vidage.
            const src=String(_rejouerResiliation);
            if(!/_fileResilVider\(\)/.test(src)) return _echec('la file n\'est jamais vidée');
            const i=src.indexOf('CLOUD.pushOne'), j=src.indexOf('_fileResilVider');
            // Le vidage vient APRÈS l'envoi : sinon un échec perdrait la demande.
