            const payables=COACH_PALIERS.filter(x=>!!x.planId()&&x.cle!=='libre').length;
            if(boutons!==payables)
              return _echec(boutons+' bouton(s) pour '+payables+' palier(s) payable(s)');
            // Les trois cartes RESTENT affichées : le coach doit voir l'échelle.
            for(const x of COACH_PALIERS) if(h.indexOf(x.titre)<0)
              return _echec('la carte « '+x.titre+' » a disparu');
