          const deux=rechercherBanque('squat bulgare',null,_cat,{}).length;
          if(!(deux<un)) return _echec('« squat bulgare » ('+deux+') n\'est pas plus étroit que « squat » ('+un+')');
          if(deux!==1) return _echec('attendu 1, obtenu '+deux);
