          if(f({muscle:'QUADRICEPS'}).length!==4) return _echec('muscle : '+f({muscle:'QUADRICEPS'}));
          if(f({materiel:'barre'}).length!==2) return _echec('matériel : '+f({materiel:'barre'}));
          const deux=f({muscle:'QUADRICEPS',materiel:'barre'});
