          if(!supprimerExercicePerso(r.fiche.slug,u)) return _echec('suppression refusée');
          if(exercicesPerso(u).length) return _echec('encore dans la liste');
          if(estFavoriExo(r.fiche.slug,u)) return _echec('reste en favori');
