            showOcrReviewModal(ocr,_athleteSessionIdx(),[]);
            importOcrExercises(_athleteSessionIdx(),ocr.length);
            if(acces) return _echec(acces+' accès au sessions_config du coach');
            // Et la branche coach SORT avant la partie athlete : loadSessionManager
            // n'y est jamais atteint.
            const src=String(importOcrExercises);
            const iCoach=src.indexOf("role==='coach'");
            const iLoad=src.indexOf('loadSessionManager()');
            const iRet=src.indexOf('return;',iCoach);
            if(iCoach<0) return _echec('la branche coach a disparu');
            if(iLoad>=0&&!(iRet<iLoad))
              return _echec('loadSessionManager est atteignable par un coach');
            return progEx.map(e=>e.name).join(',')==='SQUAT'
              ?true:_echec('l\'éditeur n\'a pas été rempli');
