          if(_cyclePalier(new Date(2026,0,31))!=='2026-01') return _echec('janvier');
          if(_cyclePalier(new Date(2026,11,1))!=='2026-12') return _echec('décembre');
          // Deux instants du MÊME mois donnent la même clé : c'est ce qui
