          const athlete={id:'a1',email:'a@t',role:'athlete',coachNotes:{a1:[{id:'n1',at:1,texte:'SECRET',tag:null}]}};
          const safe={...athlete};
          if(athlete.email!=='c@t') delete safe.coachNotes;
