    // ── LECTEUR DE CORRECTION ─────────────────────────────────────────────
    (function(){
      const _v=(o)=>Object.assign({currentTime:0,duration:30,playbackRate:1,paused:true,
        pause(){this.paused=true;},_ec:{},
        addEventListener(t,f){(this._ec[t]=this._ec[t]||[]).push(f);},
        removeEventListener(t,f){const l=this._ec[t]||[];const i=l.indexOf(f);if(i>=0)l.splice(i,1);},
        _feu(t){(this._ec[t]||[]).slice().forEach(f=>f());}},o||{});

      ok('videoStepFrame avance d\x27exactement 1/fps',(()=>{
        const v=_v({currentTime:5});
        const t=videoStepFrame(v,1,30);
        if(Math.abs(t-5-1/30)>1e-6) return _echec('t = '+t);
        const w=_v({currentTime:5});
        if(Math.abs(videoStepFrame(w,1,60)-5-1/60)>1e-6) return _echec('60 fps faux');
        return v.paused===true?true:_echec('la vidéo n\x27a pas été mise en pause');})());

      ok('videoDetectFps retombe sur 30',(()=>{
        if(videoDetectFps(_v())!==30) return _echec('sans mesure : '+videoDetectFps(_v()));
        if(videoDetectFps(null)!==30) return _echec('élément absent');
        if(videoDetectFps(_v({_rcFps:0}))!==30) return _echec('mesure absurde retenue');
        return videoDetectFps(_v({_rcFps:59.94}))===59.94
          ?true:_echec('une mesure valable doit primer');})());

      ok('videoSetLoop REFUSE un segment de plus de 10 s',(()=>{
        const v=_v();
        if(videoSetLoop(v,3,14)!==null) return _echec('11 s accepté');
        if(!videoSetLoop(v,3,13)) return _echec('10 s pile refusé');
        return videoSetLoop(v,5,5)===null?true:_echec('segment nul accepté');})());

      ok('La boucle ramène la lecture au point A',(()=>{
        const v=_v();
        videoSetLoop(v,3,7);
        v.currentTime=7.01; v._feu('timeupdate');
        if(v.currentTime!==3) return _echec('à 7 s : '+v.currentTime);
        videoClearLoop(v);
        v.currentTime=9; v._feu('timeupdate');
        if(v.currentTime!==9) return _echec('boucle non effacée');
        return (v._ec.timeupdate||[]).length===0
          ?true:_echec('l\x27écouteur est resté accroché');})());

      ok('Le ralenti ne change PAS le timecode enregistré',(()=>{
        // currentTime est le temps réel du média : il ne dépend pas de
        // playbackRate. C'est ce qui garantit la règle 2.
        const v=_v({currentTime:14.2,playbackRate:0.5});
        return secsToTs(v.currentTime)==='0:14'
          ?true:_echec(secsToTs(v.currentTime));})());

      ok('NON-RÉGRESSION : le tri des annotations, étendu et non réécrit',(()=>{
        // Deux annotations dans la MÊME seconde : seul `sec` les départage.
        // Et les annotations d'avant ce lot, sans `sec`, se trient comme avant.
        const f=x=>(x&&isFinite(Number(x.sec)))?Number(x.sec):tsToSecs(x.ts);
        const l=[{ts:'0:20',note:'c'},{ts:'0:14',note:'b',sec:14.2},
          {ts:'0:14',note:'a',sec:14.05},{ts:'0:05',note:'z'}];
        const o=l.slice().sort((a,b)=>f(a)-f(b)).map(x=>x.note).join('');
        if(o!=='zabc') return _echec('ordre : '+o);
        const anc=[{ts:'1:00',note:'x'},{ts:'0:30',note:'y'}];
        const o2=anc.slice().sort((a,b)=>f(a)-f(b)).map(x=>x.note).join('');
        if(o2!=='yx') return _echec('anciennes annotations : '+o2);
        return /_tsSec/.test(String(_renderTsAnnotations))
          ?true:_echec('la liste n\x27utilise pas le comparateur étendu');})());

      ok('NON-RÉGRESSION : le timecode reste actionnable au clavier',(()=>{
        const h=_renderTsAnnotations([{ts:'0:45',note:'genoux'}],{readonly:true,videoId:'x'});
        if(h.indexOf('tabindex="0"')<0) return _echec('le repère n\x27est plus focusable');
        if(h.indexOf('role="button"')<0) return _echec('le rôle a disparu');
        return /event\.key===.Enter./.test(h)
          ?true:_echec('la touche Entrée ne l\x27actionne plus');})());

      ok('Aucune transformation n\x27est demandée au service de médias',(()=>{
        for(const f of [videoSetRate,videoStepFrame,videoSetLoop,videoClearLoop,videoDetectFps])
          if(/fetch\(|cloudinary|\/upload\/|XMLHttpRequest/i.test(String(f)))
            return _echec('une fonction du lecteur sort sur le réseau');
        return true;})());

      ok('playsinline est posé : sans lui, iOS reprend les contrôles',(()=>{
        const h=_videoEmbed('https://x.test/a.mp4');
        if(h.indexOf('playsinline')<0) return _echec('playsinline absent');
        return h.indexOf('webkit-playsinline')>=0
          ?true:_echec('le repli des anciens iOS manque');})());

      ok('Vidéo YouTube : aucune barre de correction',(()=>{
        // L'iframe n'est pas pilotable sans le script externe de YouTube.
        const h=_videoEmbed('https://youtu.be/abcdefghijk');
        return h.indexOf('rc-barre')<0?true:_echec('une barre inerte a été posée');})());
    })();

