            const v=(i,j,kg,r)=>{sd[i].sets[j]={weight:String(kg),reps:String(r),done:true};};
            v(0,0,60,10); v(0,1,60,10); v(0,2,62.5,8); v(1,0,100,5); v(1,1,100,5);
