      mk([{name:'TAPIS DE COURSE',reps:'20 min',repos:'2 min',series:3}]);
      ok('Le cardio ne lance rien',_reposApresSerie(0,0)===null);
      // Superset : le repos est à la fin du COUPLE, pas entre les deux exercices.
