    const _guideNoms=()=>{
      const n=new Set();
      for(const sig in EX_GUIDE_BRUT) EX_GUIDE_BRUT[sig].split('~').forEach(x=>{ if(x) n.add(x); });
      EX_GUIDE_POSING.split('~').forEach(x=>{ if(x) n.add(x); });
      return n;};
