          enregistrerAnalyse(u,'hemoglobine',9,'g/dL',_j(1));
          const h=_htmlAnalyses(u);
          const txt=h.replace(/<[^>]*>/g,' ');
          const mots=/élevé|elevé|\bbas\b|\bbasse\b|normal|anormal|à surveiller|carence|excès/i;
          if(mots.test(txt)) return _echec('mot interdit dans : '+txt.slice(0,140));
          // Une valeur très haute et une très basse sont rendues à l'identique :
          // aucune couleur, aucune classe, aucun marqueur visuel de l'une ou
