        ok('La table des fruits n\'est rendue QU\'UNE FOIS, en pied',(()=>{
          const u=_pa({nutrition:Object.assign(_macros({kcal:2600,p:200,g:300,l:70,f:36}),
            {plan:{squelette:[{id:'f1',repas:'collation1',fruit:true},
              {id:'f2',repas:'petit_dej',fruit:true},
              {id:'a',repas:'midi',ciqual:4,q:250,u:'g'}],
             sources:{proteines:[],glucides:[]}}})});
          const _s=currentUser,_sDB=_ciqualDB;
          let h='';
          try{ currentUser=u; _ciqualDB=Object.keys(_AL).map(k=>_AL[k]); h=_htmlPlanAthlete(u); }
          finally{ currentUser=_s; _ciqualDB=_sDB; }
          // RÈGLE RE-INVERSÉE, sur signalement de Kevin. Elle avait été mise
          // sous CHAQUE ligne de fruit pour épargner l'aller-retour vers le
          // pied ; conséquence non vue à l'époque : un plan qui place un fruit
          // à trois repas affichait la même table de vingt lignes quatre fois.
          // Une seule table, en pied, là où le tableur la met.
          // Comptage par le DOM, pas par chaîne : le nom de l'aliment figure
          // AUSSI dans l'attribut title — la ligne est coupée, la donnée non —
          // donc un match textuel compte chaque table deux fois.
          const dd=document.createElement('div'); dd.innerHTML=h;
          const n=dd.querySelectorAll('table.p4-txt').length;
          if(n!==1) return _echec('table rendue '+n+' fois, attendu 1 (le pied seul)');
          // Les lignes de fruit restent VISIBLES dans leur repas.
          if((h.match(/Une portion de fruit au choix/g)||[]).length!==2)
            return _echec('les deux lignes de fruit ne sont pas toutes les deux affichées');
          if(/voir la table/.test(h)) return _echec('l\'ancien renvoi est resté');
          // Repliée : rien de la table ne doit s'afficher sans un geste.
          if(/<details class="plan-src"\s+open/.test(h)) return _echec('un volet est ouvert par défaut');
          return /plan-src-nb">20 fruits/.test(h)
            ?true:_echec('le volet n\'annonce pas ce qu\'il contient');})());
        ok('Les catalogues sortent en tableau à 4 colonnes, en-tête coloré',(()=>{
          const u=_pa({nutrition:Object.assign(_macros({kcal:2600,p:200,g:300,l:70,f:36}),
            {plan:{squelette:[{id:'a',repas:'midi',src:'p'},{id:'b',repas:'soir',src:'c'}],
             sources:{proteines:[5,9],glucides:[5]}}})});
          const _s=currentUser,_sDB=_ciqualDB;
          let h='';
          try{ currentUser=u; _ciqualDB=Object.keys(_AL).map(k=>_AL[k]); h=_htmlPlanAthlete(u); }
          finally{ currentUser=_s; _ciqualDB=_sDB; }
          const d=document.createElement('div'); d.innerHTML=h;
          const tables=d.querySelectorAll('table.p4');
          if(!tables.length) return _echec('aucun tableau à 4 colonnes');
          // Quatre en-têtes : aliment, quantité, aliment, quantité.
          const mauvais=[...tables].filter(t=>t.querySelectorAll('thead th').length!==4);
          if(mauvais.length) return _echec(mauvais.length+' tableau(x) sans 4 colonnes');
          // Chaque ligne porte 4 cellules, même la dernière quand le nombre
          // de sources est impair : sinon la moitié droite se décale.
          const lignesCourtes=[...tables].flatMap(t=>[...t.querySelectorAll('tbody tr')])
            .filter(r=>r.children.length!==4);
          if(lignesCourtes.length) return _echec(lignesCourtes.length+' ligne(s) incomplète(s)');
          // Code couleur des tableurs : protéines rouge, glucides jaune.
          if(!/--p4:#ff3b30/.test(h)) return _echec('les protéines ne sont pas en rouge');
          if(!/--p4:#f5c518/.test(h)) return _echec('les glucides ne sont pas en jaune');
          return true;})());
        ok('Chaque repas affiche son total de macros',(()=>{
          const u=_pa({nutrition:Object.assign(_macros({kcal:2600,p:200,g:300,l:70,f:36}),
            {plan:{squelette:[{id:'a',repas:'midi',ciqual:4,q:250,u:'g'}],
             sources:{proteines:[],glucides:[]}}})});
          const _s=currentUser,_sDB=_ciqualDB;
          let h='';
          try{ currentUser=u; _ciqualDB=Object.keys(_AL).map(k=>_AL[k]); h=_htmlPlanAthlete(u); }
          finally{ currentUser=_s; _ciqualDB=_sDB; }
          const d=document.createElement('div'); d.innerHTML=h;
          const m=d.querySelector('.plan-macros');
          if(!m) return _echec('aucun total de repas');
          // Le tilde n'est pas décoratif : les macros secondaires de la source
          // choisie ne sont pas comptables, et le total ne doit pas se donner
          // pour exact.
          return /^~\d+ kcal · \d+P \d+G \d+L$/.test(m.textContent.trim())
            ?true:_echec('format inattendu : '+m.textContent.trim());})());

